export function findSampleSociety(id: string): FullSocietyDetail | undefined {
  const norm = id.trim().toLowerCase();
  const rawId = norm.replace(/^mb_/, '');
  return SAMPLE_SOCIETIES.find((s) => s.id.toLowerCase() === norm || s.id.toLowerCase() === 'mb_' + rawId || s.id.toLowerCase().endsWith(rawId));
}
